import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);

import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";

export default function ToastExample() {
  return (
    <Button
      onClick={() => {
        toast.add({
          description: "Your changes have been saved.",
          id: "toast-demo-saved",
          title: "Saved",
        });
      }}
    >
      Show toast
    </Button>
  );
}

/// <reference lib="es2024.promise" />
import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";

const showToast = () => {
  const { promise, resolve } = Promise.withResolvers<{ name: string }>();
  window.setTimeout(() => {
    resolve({ name: "Event" });
  }, 2000);
  void toast.promise(promise, {
    error: "Could not create event.",
    loading: "Creating event…",
    success: (data) => `${data.name} created.`,
  });
};

export default function ToastPromiseExample() {
  return (
    <Button variant="outline" onClick={showToast}>
      Create Event
    </Button>
  );
}

import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";

export default function ToastTypesExample() {
  return (
    <div className="flex flex-wrap gap-related">
      <Button
        variant="outline"
        onClick={() => {
          void toast.add({ description: "Event has been created.", id: "toast-type-default" });
        }}
      >
        Default
      </Button>
      <Button
        variant="success"
        onClick={() => {
          void toast.add({
            description: "Event has been created.",
            id: "toast-type-success",
            type: "success",
          });
        }}
      >
        Success
      </Button>
      <Button
        variant="info"
        onClick={() => {
          void toast.add({
            description: "Arrive 10 minutes before the event.",
            id: "toast-type-info",
            type: "info",
          });
        }}
      >
        Info
      </Button>
      <Button
        variant="warning"
        onClick={() => {
          void toast.add({
            description: "The event cannot start before 8:00 AM.",
            id: "toast-type-warning",
            type: "warning",
          });
        }}
      >
        Warning
      </Button>
      <Button
        variant="error"
        onClick={() => {
          void toast.add({
            description: "The event could not be created.",
            id: "toast-type-error",
            priority: "high",
            type: "error",
          });
        }}
      >
        Error
      </Button>
    </div>
  );
}

